'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var tape = require( 'tape' );
var Float64Array = require( '@stdlib/array/float64' );
var tryRequire = require( '@stdlib/utils/try-require' );


// VARIABLES //

var dtrapezoid = tryRequire( resolve( __dirname, './../lib/ndarray.native.js' ) );
var opts = {
	'skip': ( dtrapezoid instanceof Error )
};


// TESTS //

tape( 'main export is a function', opts, function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof dtrapezoid, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 7', opts, function test( t ) {
	t.strictEqual( dtrapezoid.length, 7, 'returns expected value' );
	t.end();
});

tape( 'the function calculates the integral of `x` and `y`', opts, function test( t ) {
	var out;
	var x;
	var y;

	x = new Float64Array( [ 0.0, 1.0, 2.0, 3.0 ] );
	y = new Float64Array( [ 0.0, 1.0, 4.0, 9.0 ] );

	out = dtrapezoid( x.length, x, 1, 0, y, 1, 0 );
	t.strictEqual( out, 9.5, 'returns expected value' );

	x = new Float64Array( [ 0.0, 1.0, 2.0 ] );
	y = new Float64Array( [ 1.0, 2.0, 3.0 ] );

	out = dtrapezoid( x.length, x, 1, 0, y, 1, 0 );
	t.strictEqual( out, 4.0, 'returns expected value' );

	t.end();
});

tape( 'if provided an `N` parameter less than or equal to `1`, the function returns `0`', opts, function test( t ) {
	var out;
	var x;
	var y;

	x = new Float64Array( [ 0.0, 1.0, 2.0 ] );
	y = new Float64Array( [ 0.0, 1.0, 4.0 ] );

	out = dtrapezoid( 0, x, 1, 0, y, 1, 0 );
	t.strictEqual( out, 0.0, 'returns expected value' );

	out = dtrapezoid( 1, x, 1, 0, y, 1, 0 );
	t.strictEqual( out, 0.0, 'returns expected value' );

	out = dtrapezoid( -4, x, 1, 0, y, 1, 0 );
	t.strictEqual( out, 0.0, 'returns expected value' );

	t.end();
});

tape( 'the function supports an `x` stride', opts, function test( t ) {
	var out;
	var x;
	var y;

	x = new Float64Array([
		0.0,  // 0
		-1.0,
		1.0,  // 1
		-1.0,
		2.0   // 2
	]);
	y = new Float64Array([
		0.0,  // 0
		1.0,  // 1
		4.0   // 2
	]);

	out = dtrapezoid( 3, x, 2, 0, y, 1, 0 );
	t.strictEqual( out, 3.0, 'returns expected value' );

	t.end();
});

tape( 'the function supports a `y` stride', opts, function test( t ) {
	var out;
	var x;
	var y;

	x = new Float64Array([
		0.0,  // 0
		1.0,  // 1
		2.0   // 2
	]);
	y = new Float64Array([
		0.0,  // 0
		-1.0,
		1.0,  // 1
		-1.0,
		4.0   // 2
	]);

	out = dtrapezoid( 3, x, 1, 0, y, 2, 0 );
	t.strictEqual( out, 3.0, 'returns expected value' );

	t.end();
});

tape( 'the function supports an `x` offset', opts, function test( t ) {
	var out;
	var x;
	var y;

	x = new Float64Array([
		-1.0,
		0.0,  // 0
		1.0,  // 1
		2.0   // 2
	]);
	y = new Float64Array([
		0.0,  // 0
		1.0,  // 1
		4.0   // 2
	]);

	out = dtrapezoid( 3, x, 1, 1, y, 1, 0 );
	t.strictEqual( out, 3.0, 'returns expected value' );

	t.end();
});

tape( 'the function supports a `y` offset', opts, function test( t ) {
	var out;
	var x;
	var y;

	x = new Float64Array([
		0.0,  // 0
		1.0,  // 1
		2.0   // 2
	]);
	y = new Float64Array([
		-1.0,
		0.0,  // 0
		1.0,  // 1
		4.0   // 2
	]);

	out = dtrapezoid( 3, x, 1, 0, y, 1, 1 );
	t.strictEqual( out, 3.0, 'returns expected value' );

	t.end();
});

tape( 'the function supports negative `x` stride', opts, function test( t ) {
	var out;
	var x;
	var y;

	x = new Float64Array([
		2.0, // 2
		-1.0,
		1.0, // 1
		-1.0,
		0.0  // 0
	]);
	y = new Float64Array([
		0.0, // 0
		1.0, // 1
		4.0  // 2
	]);

	out = dtrapezoid( 3, x, -2, 4, y, 1, 0 );
	t.strictEqual( out, 3.0, 'returns expected value' );

	t.end();
});

tape( 'the function supports negative `y` stride', opts, function test( t ) {
	var out;
	var x;
	var y;

	x = new Float64Array([
		0.0, // 0
		1.0, // 1
		2.0  // 2
	]);
	y = new Float64Array([
		4.0, // 2
		-1.0,
		1.0, // 1
		-1.0,
		0.0  // 0
	]);

	out = dtrapezoid( 3, x, 1, 0, y, -2, 4 );
	t.strictEqual( out, 3.0, 'returns expected value' );

	t.end();
});

tape( 'the function supports complex access patterns', opts, function test( t ) {
	var out;
	var x;
	var y;

	x = new Float64Array([
		0.0, // 0
		1.0,
		1.0, // 1
		2.0,
		2.0  // 2
	]);
	y = new Float64Array([
		4.0, // 2
		3.0, // 1
		0.0, // 0
		1.0,
		2.0
	]);

	out = dtrapezoid( 3, x, 2, 0, y, -1, 2 );
	t.strictEqual( out, 5.0, 'returns expected value' );

	t.end();
});

tape( 'if both strides are equal to `1`, the function efficiently calculates the integral', opts, function test( t ) {
	var out;
	var x;
	var y;
	var i;

	x = new Float64Array( 100 );
	y = new Float64Array( x.length );
	for ( i = 0; i < x.length; i++ ) {
		x[ i ] = i;
		y[ i ] = i * i;
	}
	out = dtrapezoid( x.length, x, 1, 0, y, 1, 0 );
	t.strictEqual( out, 323449.5, 'returns expected value' );

	x = new Float64Array( 240 );
	y = new Float64Array( x.length );
	for ( i = 0; i < x.length; i++ ) {
		x[ i ] = i;
		y[ i ] = i * i;
	}
	out = dtrapezoid( x.length, x, 1, 0, y, 1, 0 );
	t.strictEqual( out, 4550679.5, 'returns expected value' );

	t.end();
});
